CREATE TABLE "saturnalia_admins" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "username" TEXT COLLATE NOCASE NOT NULL, "password" TEXT COLLATE NOCASE NOT NULL, "name" TEXT COLLATE NOCASE NOT NULL, "permission" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "saturnalia_anonymous" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "whom" TEXT COLLATE NOCASE NOT NULL, "jot" TEXT COLLATE NOCASE NOT NULL, "who" TEXT COLLATE NOCASE NOT NULL, "like_shaheen" INTEGER NOT NULL DEFAULT '0', "like_siddharth" INTEGER NOT NULL DEFAULT '0', "like_abhinav" INTEGER NOT NULL DEFAULT '0', "like_rohit" INTEGER NOT NULL DEFAULT '0', "like_rohaan" INTEGER NOT NULL DEFAULT '0', "like_ratnav" INTEGER NOT NULL DEFAULT '0', "edited" INTEGER NOT NULL DEFAULT '0');

CREATE TABLE "saturnalia_anonymous_deleted" ("entry_id" INTEGER PRIMARY KEY AUTOINCREMENT, "id" INTEGER NOT NULL, "whom" TEXT COLLATE NOCASE NOT NULL, "jot" TEXT COLLATE NOCASE NOT NULL, "who" TEXT COLLATE NOCASE NOT NULL, "deleted_by" INTEGER NOT NULL, "timestamp" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "saturnalia_anonymous_updates" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "entry_id" INTEGER NOT NULL, "old_whom" TEXT COLLATE NOCASE NOT NULL, "old_jot" TEXT COLLATE NOCASE NOT NULL, "old_who" TEXT COLLATE NOCASE NOT NULL, "updated_by_id" INTEGER NOT NULL, "datetime" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "saturnalia_attendance" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "clg_reg" INTEGER NOT NULL, "name" TEXT COLLATE NOCASE NOT NULL, "category" TEXT COLLATE NOCASE NOT NULL, "attendance" INTEGER NOT NULL DEFAULT '0', "time_entered" TEXT COLLATE NOCASE NOT NULL, "entered_by" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "saturnalia_yearbook" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" TEXT COLLATE NOCASE NOT NULL, "clg_reg" INTEGER NOT NULL, "dob" TEXT COLLATE NOCASE NOT NULL, "address" TEXT COLLATE NOCASE NOT NULL, "nickname" TEXT COLLATE NOCASE NOT NULL, "phone" TEXT COLLATE NOCASE NOT NULL, "email" TEXT COLLATE NOCASE NOT NULL, "social" TEXT COLLATE NOCASE NOT NULL, "dean" TEXT COLLATE NOCASE NOT NULL, "gave_up" TEXT COLLATE NOCASE NOT NULL, "gold" TEXT COLLATE NOCASE NOT NULL, "not_doc" TEXT COLLATE NOCASE NOT NULL, "life_changing" TEXT COLLATE NOCASE NOT NULL, "omg" TEXT COLLATE NOCASE NOT NULL, "day_join" TEXT COLLATE NOCASE NOT NULL, "6_skills" TEXT COLLATE NOCASE NOT NULL, "quote" TEXT COLLATE NOCASE NOT NULL, "testimonial" TEXT COLLATE NOCASE NOT NULL);

CREATE UNIQUE INDEX "saturnalia_yearbook_clg_reg" ON "saturnalia_yearbook" ("clg_reg");
